38	    @Column(name = "address")
39	    @NotEmpty
40	    private String address;
41	
42	    @Column(name = "city")
43	    @NotEmpty
44	    private String city;
45	
46	    @Column(name = "telephone")
47	    @NotEmpty
48	    @Pattern(regexp = "^\\+[0-9]{8,15}$", message = "Phone number must be in E.164 format")
49	    private String telephone;
50	
51	    @Column(name = "email")
52	    private String email;
53	
54	    @Column(name = "registration_date")
55	    private LocalDate registrationDate;
56	
57	    @Column(name = "customer_code")
58	    private String customerCode;
59	
60	    @Column(name = "household_id")
61	    private String householdId;
62	
63	    @Column(name = "namesake_count")
64	    private Integer namesakeCount;
65	
66	    @Column(name = "household_size")
67	    private Integer householdSize;
68	
69	    @OneToMany(cascade = CascadeType.ALL, mappedBy = "owner", fetch = FetchType.EAGER)
70	    private Set<Pet> pets;
71	
72	    public String getAddress() {
73	        return this.address;
74	    }
75	
76	    public void setAddress(String address) {
77	        this.address = address;
78	    }
79	
80	    public String getCity() {
81	        return this.city;
82	    }
83	
84	    public void setCity(String city) {
85	        this.city = city;
86	    }
87	
88	    public String getTelephone() {
89	        return this.telephone;
90	    }
91	
92	    public void setTelephone(String telephone) {
93	        this.telephone = telephone;
94	    }
95	
96	    public String getEmail() {
97	        return this.email;
98	    }
99	
100	    public void setEmail(String email) {
101	        this.email = email;
102	    }
103	
104	    public LocalDate getRegistrationDate() {
105	        return this.registrationDate;
106	    }
107	
108	    public void setRegistrationDate(LocalDate registrationDate) {
109	        this.registrationDate = registrationDate;
110	    }
111	
112	    public String getCustomerCode() {
113	        return this.customerCode;
114	    }
115	
116	    public void setCustomerCode(String customerCode) {
117	        this.customerCode = customerCode;
118	    }
119	
120	    public String getHouseholdId() {
121	        return this.householdId;
122	    }
123	
124	    public void setHouseholdId(String householdId) {
125	        this.householdId = householdId;
126	    }
127	
128	    public Integer getNamesakeCount() {
129	        return this.namesakeCount;
130	    }
131	
132	    public void setNamesakeCount(Integer namesakeCount) {
133	        this.namesakeCount = namesakeCount;
134	    }
135	
136	    public Integer getHouseholdSize() {
137	        return this.householdSize;
138	    }
139	
140	    public void setHouseholdSize(Integer householdSize) {
141	        this.householdSize = householdSize;
142	    }
143	
144	    /**
145	     * The owner's identity key: the single derived value used to detect duplicate owners, formed
146	     * as {@code normalizedTelephone + '|' + email + '|' + householdId} where an absent telephone,
147	     * email or household contributes an empty string. Two owners are duplicates only when their
148	     * whole identity keys are equal, so housemates that share a {@code householdId} but hold
149	     * different telephones have distinct identity keys and are both allowed.
150	     */
151	    public String getIdentityKey() {
152	        return orEmpty(this.telephone) + "|" + orEmpty(this.email) + "|" + orEmpty(this.householdId);
153	    }
154	
155	    private static String orEmpty(String value) {
156	        return value == null ? "" : value;
157	    }
158	
159	    /**
160	     * The owner's membership number, formatted {@code '<customerCode>-M<YY>'} where YY is the
161	     * last two digits of the registration date's year (e.g. {@code 'SMI-0007-M26'}). Derived
162	     * from the owner's own fields; absent until both the customer code and registration date
163	     * have been assigned.
164	     */
165	    public String getMembershipNumber() {
166	        if (this.customerCode == null || this.registrationDate == null) {
167	            return null;
168	        }
169	        return String.format("%s-M%02d", this.customerCode, this.registrationDate.getYear() % 100);
170	    }
171	
172	    /**
173	     * The owner's membership level, a number from 1 to 3 derived from the owner's own fields:
174	     * every owner starts at level 1, gains a level when an email address is present, and gains a
175	     * further level when this owner has no namesakes ({@code namesakeCount} is 0). The result is
176	     * capped at 3; level 4 is reserved for tenure.
177	     */
178	    public Integer getMembershipLevel() {
179	        int level = 1;
180	        boolean hasEmail = this.email != null && !this.email.isEmpty();
181	        if (hasEmail) {
182	            level++;
183	        }
184	        boolean unique = this.namesakeCount != null && this.namesakeCount == 0;
185	        if (unique) {
186	            level++;
187	        }
188	        return Math.min(level, 3);
189	    }
190	
191	    /**
192	     * Fixed city-to-region lookup backing {@link #getLocality()}. Cities absent from this
193	     * table derive the locality {@code "UNKNOWN"}.
194	     */
195	    private static final Map<String, String> CITY_REGIONS =
196	        Map.of("Sydney", "NSW", "Melbourne", "VIC", "Brisbane", "QLD");
197	
198	    /**
199	     * The owner's locality: the canonical region derived from {@link #getCity() city} using the
200	     * fixed {@link #CITY_REGIONS} table, or {@code "UNKNOWN"} when the city is not in the table.
201	     */
202	    public String getLocality() {
203	        return CITY_REGIONS.getOrDefault(this.city, "UNKNOWN");
204	    }
205	
206	    /**
207	     * The owner's preferred contact channel, derived from the owner's own fields:
208	     * {@code "EMAIL"} when an {@link #getEmail() email} is present, otherwise {@code "PHONE"}.
209	     */
210	    public String getContactPreference() {
211	        boolean hasEmail = this.email != null && !this.email.isEmpty();
212	        return hasEmail ? "EMAIL" : "PHONE";
213	    }
214	
215	    /**
216	     * Resolve the effective registration date before persisting: default it to the server's
217	     * current date when none was supplied, then roll it forward off weekends so a newly
218	     * registered owner always has a business-day registration date. Every value derived from it
219	     * (such as the {@link #getMembershipNumber() membership number}) therefore uses the adjusted
220	     * date.
221	     */
222	    @PrePersist
223	    private void resolveRegistrationDate() {
224	        if (this.registrationDate == null) {
225	            this.registrationDate = LocalDate.now();
226	        }
227	        this.registrationDate = BusinessDay.onOrAfter(this.registrationDate);
228	    }
229	
230	    protected Set<Pet> getPetsInternal() {
231	        if (this.pets == null) {
232	            this.pets = new HashSet<>();
233	        }
234	        return this.pets;
235	    }
236	
237	    protected void setPetsInternal(Set<Pet> pets) {
238	        this.pets = pets;
239	    }
240	
241	    public List<Pet> getPets() {
242	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
243	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
244	        return Collections.unmodifiableList(sortedPets);
245	    }
246	
247	    public void setPets(List<Pet> pets) {
248	        this.pets = new HashSet<>(pets);
249	    }
250	
251	    public void addPet(Pet pet) {
252	        getPetsInternal().add(pet);
253	        pet.setOwner(this);
254	    }
255	
256	    /**
257	     * Return the Pet with the given name, or null if none found for this Owner.
258	     *
259	     * @param name to test
260	     * @return true if pet name is already in use
261	     */
262	    public Pet getPet(String name) {
263	        return getPet(name, false);
264	    }
265	
266	    /**
267	     * Return the Pet with the given name, or null if none found for this Owner.
268	     *
269	     * @param name to test
270	     * @return true if pet name is already in use
271	     */
272	    public Pet getPet(String name, boolean ignoreNew) {
273	        name = name.toLowerCase();
274	        for (Pet pet : getPetsInternal()) {
275	            if (!ignoreNew || !pet.isNew()) {
276	                String compName = pet.getName();
277	                compName = compName.toLowerCase();
278	                if (compName.equals(name)) {
279	                    return pet;
280	                }
281	            }
282	        }
283	        return null;
284	    }
285	
286	    public Pet getPet(Integer petId) {
287	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
288	    }
289	
290	    @Override
291	    public String toString() {
292	        return new ToStringCreator(this)
293	
294	            .append("id", this.getId())
295	            .append("new", this.isNew())
296	            .append("lastName", this.getLastName())
297	            .append("firstName", this.getFirstName())
298	            .append("address", this.address)
299	            .append("city", this.city)
300	            .append("telephone", this.telephone)
301	            .append("email", this.email)
302	            .toString();
