35	import org.springframework.samples.petclinic.rest.dto.PetFieldsDto;
36	import org.springframework.samples.petclinic.rest.dto.VisitDto;
37	import org.springframework.samples.petclinic.rest.dto.VisitFieldsDto;
38	import org.springframework.samples.petclinic.rest.assignment.CustomerCodeGenerator;
39	import org.springframework.samples.petclinic.rest.assignment.HouseholdIdGenerator;
40	import org.springframework.samples.petclinic.rest.assignment.HouseholdRegistrar;
41	import org.springframework.samples.petclinic.rest.audit.OwnerAuditLogger;
42	import org.springframework.samples.petclinic.rest.signup.BulkSignupWarningEvaluator;
43	import org.springframework.samples.petclinic.rest.validation.AddressNormalizer;
44	import org.springframework.samples.petclinic.rest.validation.CityOwnerLimitValidator;
45	import org.springframework.samples.petclinic.rest.validation.DailyOwnerLimitValidator;
46	import org.springframework.samples.petclinic.rest.validation.DuplicateOwnerValidator;
47	import org.springframework.samples.petclinic.rest.validation.EmailNormalizer;
48	import org.springframework.samples.petclinic.rest.validation.OwnerRequestValidator;
49	import org.springframework.samples.petclinic.rest.validation.TelephoneNormalizer;
50	import org.springframework.samples.petclinic.service.ClinicService;
51	import org.springframework.security.access.prepost.PreAuthorize;
52	import org.springframework.web.bind.annotation.CrossOrigin;
53	import org.springframework.web.bind.annotation.RequestMapping;
