58	
59	/**
60	 * @author Vitaliy Fedoriv
61	 */
62	
63	@RestController
64	@CrossOrigin(exposedHeaders = "errors, content-type")
65	@RequestMapping("/api")
66	public class OwnerRestControllerV1 implements OwnersApi {
67	
68	    private final ClinicService clinicService;
69	
70	    private final OwnerMapper ownerMapper;
71	
72	    private final PetMapper petMapper;
73	
74	    private final VisitMapper visitMapper;
75	
76	    private final OwnerRequestValidator ownerRequestValidator;
77	
78	    private final DuplicateOwnerValidator duplicateOwnerValidator;
79	
80	    private final CityOwnerLimitValidator cityOwnerLimitValidator;
81	
82	    private final DailyOwnerLimitValidator dailyOwnerLimitValidator;
83	
84	    private final TelephoneNormalizer telephoneNormalizer;
85	
86	    private final EmailNormalizer emailNormalizer;
87	
88	    private final AddressNormalizer addressNormalizer;
89	
90	    private final CustomerCodeGenerator customerCodeGenerator;
91	
92	    private final HouseholdIdGenerator householdIdGenerator;
93	
94	    private final HouseholdRegistrar householdRegistrar;
95	
96	    private final OwnerAuditLogger ownerAuditLogger;
97	
98	    private final BulkSignupWarningEvaluator bulkSignupWarningEvaluator;
99	
100	    public OwnerRestControllerV1(ClinicService clinicService,
101	                                 OwnerMapper ownerMapper,
102	                                 PetMapper petMapper,
103	                                 VisitMapper visitMapper,
104	                                 OwnerRequestValidator ownerRequestValidator,
105	                                 DuplicateOwnerValidator duplicateOwnerValidator,
106	                                 CityOwnerLimitValidator cityOwnerLimitValidator,
107	                                 DailyOwnerLimitValidator dailyOwnerLimitValidator,
108	                                 TelephoneNormalizer telephoneNormalizer,
109	                                 EmailNormalizer emailNormalizer,
110	                                 AddressNormalizer addressNormalizer,
111	                                 CustomerCodeGenerator customerCodeGenerator,
112	                                 HouseholdIdGenerator householdIdGenerator,
113	                                 HouseholdRegistrar householdRegistrar,
114	                                 OwnerAuditLogger ownerAuditLogger,
115	                                 BulkSignupWarningEvaluator bulkSignupWarningEvaluator) {
116	        this.clinicService = clinicService;
117	        this.ownerMapper = ownerMapper;
118	        this.petMapper = petMapper;
119	        this.visitMapper = visitMapper;
120	        this.ownerRequestValidator = ownerRequestValidator;
121	        this.duplicateOwnerValidator = duplicateOwnerValidator;
122	        this.cityOwnerLimitValidator = cityOwnerLimitValidator;
123	        this.dailyOwnerLimitValidator = dailyOwnerLimitValidator;
124	        this.telephoneNormalizer = telephoneNormalizer;
125	        this.emailNormalizer = emailNormalizer;
126	        this.addressNormalizer = addressNormalizer;
127	        this.customerCodeGenerator = customerCodeGenerator;
128	        this.householdIdGenerator = householdIdGenerator;
129	        this.householdRegistrar = householdRegistrar;
130	        this.ownerAuditLogger = ownerAuditLogger;
131	        this.bulkSignupWarningEvaluator = bulkSignupWarningEvaluator;
132	    }
133	
134	    /**
135	     * Map an owner to its DTO and stamp the current bulk-signup warning onto it, so every
136	     * single-owner response reflects whether more than 80 owners have been created today.
137	     */
138	    private OwnerDto toOwnerDto(Owner owner) {
139	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
140	        ownerDto.setBulkSignupWarning(this.bulkSignupWarningEvaluator.isBulkSignupInEffect());
141	        return ownerDto;
142	    }
143	
144	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
145	    @Override
146	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
147	        Collection<Owner> owners;
148	        if (lastName != null) {
149	            owners = this.clinicService.findOwnerByLastName(lastName);
150	        } else {
151	            owners = this.clinicService.findAllOwners();
152	        }
153	        if (owners.isEmpty()) {
154	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
155	        }
156	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
157	    }
158	
159	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
160	    @Override
161	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
162	        Owner owner = this.clinicService.findOwnerById(ownerId);
163	        if (owner == null) {
164	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
165	        }
166	        return new ResponseEntity<>(toOwnerDto(owner), HttpStatus.OK);
167	    }
168	
169	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
170	    @Override
171	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
172	        ownerFieldsDto.setAddress(this.addressNormalizer.normalize(ownerFieldsDto.getAddress()));
173	        this.ownerRequestValidator.validate(ownerFieldsDto);
174	        this.cityOwnerLimitValidator.validate(ownerFieldsDto);
175	        this.dailyOwnerLimitValidator.validate(ownerFieldsDto.getRegistrationDate());
176	        ownerFieldsDto.setTelephone(this.telephoneNormalizer.normalize(ownerFieldsDto.getTelephone()));
177	        ownerFieldsDto.setEmail(this.emailNormalizer.normalize(ownerFieldsDto.getEmail()));
178	        HttpHeaders headers = new HttpHeaders();
179	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
180	        boolean sharesHousehold = Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold());
181	        if (sharesHousehold) {
182	            owner.setHouseholdId(
183	                this.householdIdGenerator.generate(owner.getLastName(), owner.getAddress()));
184	        }
185	        this.duplicateOwnerValidator.validate(owner);
186	        owner.setCustomerCode(
187	            this.customerCodeGenerator.generate(owner.getCity(), owner.getLastName(),
188	                this.clinicService.countOwnersInCity(owner.getCity())));
189	        owner.setNamesakeCount(
190	            (int) this.clinicService.countNamesakes(owner.getFirstName(), owner.getLastName()));
191	        if (sharesHousehold) {
192	            owner.setHouseholdSize(this.householdRegistrar.register(owner));
193	        }
194	        this.clinicService.saveOwner(owner);
195	        this.ownerAuditLogger.created(owner);
196	        OwnerDto ownerDto = toOwnerDto(owner);
197	        headers.setLocation(UriComponentsBuilder.newInstance()
198	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
199	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
200	    }
201	
202	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
203	    @Override
204	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
205	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
206	        if (currentOwner == null) {
207	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
208	        }
209	        currentOwner.setAddress(ownerFieldsDto.getAddress());
210	        currentOwner.setCity(ownerFieldsDto.getCity());
211	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
212	        currentOwner.setLastName(ownerFieldsDto.getLastName());
213	        currentOwner.setTelephone(this.telephoneNormalizer.normalize(ownerFieldsDto.getTelephone()));
214	        currentOwner.setEmail(this.emailNormalizer.normalize(ownerFieldsDto.getEmail()));
215	        this.clinicService.saveOwner(currentOwner);
216	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
217	    }
218	
219	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
220	    @Transactional
221	    @Override
222	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
223	        Owner owner = this.clinicService.findOwnerById(ownerId);
224	        if (owner == null) {
225	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
226	        }
227	        this.clinicService.deleteOwner(owner);
228	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
229	    }
230	
231	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
232	    @Override
233	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
234	        Owner owner = this.clinicService.findOwnerById(ownerId);
235	        if (owner == null) {
236	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
237	        }
238	        HttpHeaders headers = new HttpHeaders();
